def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i]: max sum of an increasing subsequence ending at index i
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # dec[i]: max sum of a decreasing subsequence starting at index i
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # Peak at i is counted in both halves, so subtract it once
    return max(inc[i] + dec[i] - arr[i] for i in range(n))
